select m83_reject('select public.process_assessment_workspace(m83_id(''b''),m83_id(''vacancy''))','42501');
select m83_reject('select private.get_position_follow_up_cycle(m83_id(''a''),m83_id(''vacancy''),null,null)','42501');
select m83_reject('select public.position_assessment_public(''load'',repeat(''a'',64))','42501');
select m83_reject(format('select public.position_assessment_generation_request(%L,%L,%L,%L)',m83_id('a'),(select value->>'id' from pa_state where key='reuse'),m83_id('over-20'),jsonb_build_array(jsonb_build_object('requirementId',m83_id('req'),'difficulty','easy','quantity',21))),'22023');
