select m83_assert((select profiles from pa_preservation)=(select jsonb_agg(to_jsonb(x)) from public.professional_profiles x),'profiles preserved');
select m83_assert((select matching from pa_preservation) is not distinct from (select jsonb_agg(to_jsonb(x)) from public.match_evaluations x),'matching preserved');
select m83_assert((select positions from pa_preservation)=(select jsonb_agg(to_jsonb(x)) from public.vacancies x),'positions preserved');
do $$ begin begin
 delete from public.people where organization_id=m83_id('a') and id=m83_id('late-person');
 perform m83_assert(not exists(select 1 from public.position_assessment_attempts where person_id=m83_id('late-person')),'explicit person erasure removes own applications');
 perform m83_assert(not exists(select 1 from public.position_assessment_batches b,jsonb_array_elements(b.receipts) r where r->>'personId'=m83_id('late-person')::text),'explicit erasure removes personal batch receipts');
 perform m83_assert(exists(select 1 from public.position_assessments where process_id=(select (value->>'id')::uuid from pa_state where key='process-before')),'erasure of participant preserves common test');
 raise exception 'rollback erasure fixture' using errcode='ZX001';exception when sqlstate 'ZX001' then null;end;end $$;
-- Budget and late-generation proofs use subtransactions and restore the confirmed draft.
do $$ declare a jsonb; g jsonb; p jsonb; q jsonb; begin begin
 a:=public.process_assessment_workspace(m83_id('a'),m83_id('vacancy'))->'assessment';
 a:=public.position_assessment_mutate(m83_id('a'),m83_id('vacancy'),null,'configure',(a->>'id')::uuid,(a->>'revision')::integer,jsonb_build_object('config',jsonb_build_object('quantity',10,'level',1,'durationMinutes',60,'mode','ai'),'requirementIds',jsonb_build_array(m83_id('req'))));
 g:=public.position_assessment_generation_request(m83_id('a'),(a->>'id')::uuid,m83_id('late-generation'),jsonb_build_array(jsonb_build_object('requirementId',m83_id('req'),'difficulty','easy','quantity',1)));
 perform m83_reject(format('select public.position_assessment_mutate(%L,%L,null,''questions'',%L,%s,''{"questions":[]}'')',m83_id('a'),m83_id('vacancy'),a->>'id',a->>'revision'),'40001');
 p:=public.get_position_follow_up(m83_id('a'),m83_id('vacancy'))->'process';
 perform public.mutate_position_follow_up_process(m83_id('a'),m83_id('vacancy'),(p->>'id')::uuid,'close_process',null,(p->>'revision')::integer);
 select value->0 into q from pa_state where key='questions';
 perform m83_reject(format('select public.position_assessment_generation_finish(%L,%L,%L,0.01,true)',m83_id('late-generation'),m83_id('a'),jsonb_build_array(q)),'42501');
 perform m83_assert((public.process_assessment_workspace(m83_id('a'),m83_id('vacancy'))#>'{assessment,questions}')='[]','closed context rejects late generation without overwriting draft');
 raise exception 'rollback generation fixture' using errcode='ZX001';exception when sqlstate 'ZX001' then null;end;
 begin
 a:=public.process_assessment_workspace(m83_id('a'),m83_id('vacancy'))->'assessment';
 a:=public.position_assessment_mutate(m83_id('a'),m83_id('vacancy'),null,'configure',(a->>'id')::uuid,(a->>'revision')::integer,jsonb_build_object('config',jsonb_build_object('quantity',10,'level',1,'durationMinutes',60,'mode','ai'),'requirementIds',jsonb_build_array(m83_id('req'))));
 insert into public.position_assessment_generation(id,organization_id,assessment_id,actor_id,revision,distribution,requirements,status,actual_usd,reserved_usd) values(m83_id('monthly-cap'),m83_id('a'),(a->>'id')::uuid,m83_id('recruiter'),(a->>'revision')::integer,'[]','[]','succeeded',10,0.25);
 perform m83_reject(format('select public.position_assessment_generation_request(%L,%L,%L,%L)',m83_id('a'),a->>'id',m83_id('over-monthly'),jsonb_build_array(jsonb_build_object('requirementId',m83_id('req'),'difficulty','easy','quantity',1))),'22023');
 raise exception 'rollback budget fixture' using errcode='ZX001';exception when sqlstate 'ZX001' then null;end;
end $$;
